/**
 * The inbox's sounds, base64-encoded rather than shipped as files.
 *
 * Four short clips, ~100KB in total. Inlined because the package is built by svelte-package
 * and bundled by `bun build` for the CLI, and neither is guaranteed to carry a binary asset
 * through to `dist` — a sound that silently stops existing once published is worse than an
 * ugly constant.
 */

/** One clip: its MIME type, and its bytes as base64. */
export interface Sound {
	type: string
	data: string
}

/** Clips by name. Served by the inbox at `/__postboi/api/sounds/:name`. */
export const SOUNDS: Record<string, Sound> = {
	welcome: {
		type: "audio/wav",
		data: "",
	},
	mail: {
		type: "audio/wav",
		data: "",
	},
	goodbye: {
		type: "audio/wav",
		data: "",
	},
	dialup: {
		type: "audio/mpeg",
		data: "",
	},
}
